await writeFile(resolve(root,'revisao-consolidada.json'),JSON.stringify({geradoEm:new Date().toISOString(),contagem,arquivos:registros,componentes:componentes.length,componentesComExecucaoObservada:componentes.filter(c=>c.evidencias.length).length},null,2));
