 tabelaTempos=`<p>${perf.resultados.length} aberturas registradas; ${perf.falhas.length} falhas de cenário. ${a('velocidade-final-v2/resultados.json','Medições e requisições brutas')} · ${a('tempos-antes-depois.csv','Resumo em CSV')}</p><div class="tabela"><table><thead><tr><th>Dispositivo</th><th>Módulo</th><th>N antes/depois</th><th>Mediana antes</th><th>Mediana depois</th><th>Variação</th><th>P95 antes/depois</th><th>Máximo antes/depois</th></tr></thead><tbody>${linhas.map(r=>`<tr><td>${r.dispositivo}</td><td>${r.modulo}</td><td>${r.amostrasAntes}/${r.amostrasDepois}</td><td>${fmt(r.medianaAntes)} s</td><td>${fmt(r.medianaDepois)} s</td><td class="${r.medianaDepois>r.medianaAntes?'atencao':'ok'}">${((r.medianaDepois/r.medianaAntes-1)*100).toFixed(1)}%</td><td>${fmt(r.p95Antes)} / ${fmt(r.p95Depois)} s</td><td>${fmt(r.maxAntes)} / ${fmt(r.maxDepois)} s</td></tr>`).join('')}</tbody></table></div>`;
